def SV(node, key, val):
    """guarded socket default_value setter (Blender 5.2 renamed/unavailable sockets segfault)"""
    try:
        ins = node.inputs
        if isinstance(key, str):
            s = ins.get(key)
            if s is None: s = next((x for x in ins if x.identifier == key), None)
        else:
            s = ins[key] if 0 <= key < len(ins) else None
        if s is None or not hasattr(s, "default_value") or not getattr(s, "enabled", True) or getattr(s, "is_unavailable", False):
            NOTES.append("SV skip %s.%s" % (getattr(node, "bl_idname", "?"), key)); return False
        dv = s.default_value
        if isinstance(val, (tuple, list)) or hasattr(val, "__len__"):
            if not hasattr(dv, "__len__"): NOTES.append("SV type %s.%s" % (node.bl_idname, key)); return False
            v = tuple(val); k = len(dv)
            v = v[:k] if len(v) >= k else v + (1.0,) * (k - len(v))
            s.default_value = v
        else:
            if hasattr(dv, "__len__"): NOTES.append("SV scalar->vec %s.%s" % (node.bl_idname, key)); return False
            s.default_value = type(dv)(val) if isinstance(dv, (int, float, bool)) else val
        return True
    except Exception as e:
        NOTES.append("SV err %s %s" % (key, type(e).__name__)); return False
