# ---------------------------------------------------------------- downloads
UA = {"User-Agent": "blenderkit/3.21.3 (Blender 5.2.3)", "accept": "application/json"}
def get_key():
    for name, ad in bpy.context.preferences.addons.items():
        if "blenderkit" in name.lower():
            return getattr(ad.preferences, "api_key", "") or ""
    return ""
KEY = get_key()

BK = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "bk.json")))

def fetch(url, path, timeout=600):
    req = urllib.request.Request(url, headers={"User-Agent": UA["User-Agent"]})
    with urllib.request.urlopen(req, timeout=timeout) as r, open(path + ".part", "wb") as f:
        while True:
            b = r.read(1 << 20)
            if not b: break
            f.write(b)
    os.replace(path + ".part", path)

def bk_file(key):
    if key not in BK: NOTES.append("noBK " + key); return None
    aid, durl = BK[key]
    p = os.path.join(ADIR, "bk_" + aid + ".blend")
    if os.path.exists(p) and os.path.getsize(p) > 1000: return p
    errs = []
    for host_url in [durl, durl.replace("www.blenderkit.com", "api.blenderkit.com")]:
        try:
            h = dict(UA); h["Authorization"] = "Bearer " + KEY
            q = host_url + "?" + urllib.parse.urlencode({"scene_uuid": str(uuid.uuid4())})
            r = urllib.request.urlopen(urllib.request.Request(q, headers=h), timeout=60)
            fp = json.loads(r.read().decode())["filePath"]
            fetch(fp, p)
            return p
        except Exception as e:
            errs.append(type(e).__name__ + ":" + str(getattr(e, "code", ""))[:6])
    NOTES.append("BK " + key + " " + "/".join(errs))
    return None

PH = "https://dl.polyhaven.org/file/ph-assets/"
def ph_tex(name, kind):
    p = os.path.join(ADIR, "ph_%s_%s_1k.jpg" % (name, kind))
    if not os.path.exists(p):
        try: fetch(PH + "Textures/jpg/1k/%s/%s_%s_1k.jpg" % (name, name, kind), p)
        except Exception:
            NOTES.append("PH " + name + kind); return None
    return p

def ph_hdri(name):
    p = os.path.join(ADIR, "ph_%s_2k.hdr" % name)
    if not os.path.exists(p):
        try: fetch(PH + "HDRIs/hdr/2k/%s_2k.hdr" % name, p)
        except Exception: NOTES.append("PH hdri " + name); return None
    return p

def ph_model(name):
    """download a Poly Haven model (.blend + its textures) and return the .blend path"""
    d = os.path.join(ADIR, "phm_" + name); os.makedirs(d, exist_ok=True)
    p = os.path.join(d, name + "_1k.blend")
    if os.path.exists(p) and os.path.getsize(p) > 1000: return p
    try:
        js = json.loads(urllib.request.urlopen(urllib.request.Request("https://api.polyhaven.com/files/" + name, headers={"User-Agent": "mc43"}), timeout=60).read())
        b = js["blend"]["1k"]["blend"]
        for rel, inf in (b.get("include") or {}).items():
            tp = os.path.join(d, rel); os.makedirs(os.path.dirname(tp), exist_ok=True)
            if not os.path.exists(tp): fetch(inf["url"], tp)
        fetch(b["url"], p)
        return p
    except Exception as e:
        NOTES.append("PHM " + name + " " + type(e).__name__); return None

def link(o, coll=None):
    (coll or ROOT).objects.link(o); return o

def setattr_safe(obj, attr, val):
    try: setattr(obj, attr, val); return True
    except Exception: return False

# ---------------------------------------------------------------- materials
MATS = {}
def mat(name, col=(0.8, 0.8, 0.8), rough=0.5, metal=0.0, emit=None, es=1.0, alpha=1.0, coat=0.0, trans=0.0, ior=1.45):
    if name in MATS: return MATS[name]
    m = bpy.data.materials.new(name); m.use_nodes = True
    b = m.node_tree.nodes.get("Principled BSDF")
    SV(b, "Base Color", (*col, 1))
    SV(b, "Roughness", rough)
    SV(b, "Metallic", metal)
    try: SV(b, "Coat Weight", coat)
    except Exception: pass
    if trans:
        try: SV(b, "Transmission Weight", trans); SV(b, "IOR", ior)
        except Exception: pass
    if emit:
        SV(b, "Emission Color", (*emit, 1))
        SV(b, "Emission Strength", es)
    if alpha < 1:
        SV(b, "Alpha", alpha)
        setattr_safe(m, "surface_render_method", "BLENDED")
    MATS[name] = m
    return m

def texmat(name, tex, scale=1.0, tint=(1, 1, 1), rough_mul=1.0, bump=1.0, metal=0.0, emit=None, es=0.0):
    if name in MATS: return MATS[name]
    m = bpy.data.materials.new(name); m.use_nodes = True
    nt = m.node_tree; N = nt.nodes; L = nt.links
    b = N.get("Principled BSDF")
    SV(b, "Metallic", metal)
    tc = N.new("ShaderNodeTexCoord"); mp = N.new("ShaderNodeMapping")
    SV(mp, "Scale", (scale, scale, scale))
    L.new(tc.outputs["Object"], mp.inputs["Vector"])
    def img(kind, noncolor):
        p = ph_tex(tex, kind)
        if not p: return None
        n = N.new("ShaderNodeTexImage"); n.image = bpy.data.images.load(p, check_existing=True)
        n.projection = "BOX"; n.projection_blend = 0.25
        if noncolor: n.image.colorspace_settings.name = "Non-Color"
        L.new(mp.outputs["Vector"], n.inputs["Vector"]); return n
    d = img("diff", False)
    if d:
        mix = N.new("ShaderNodeMix"); mix.data_type = "RGBA"; mix.blend_type = "MULTIPLY"
        SV(mix, "Factor", 1.0)
        L.new(d.outputs["Color"], mix.inputs[6]); SV(mix, 7, (*tint, 1))
        L.new(mix.outputs[2], b.inputs["Base Color"])
    else:
        SV(b, "Base Color", (*tint, 1))
    r = img("rough", True)
    if r:
        mr = N.new("ShaderNodeMath"); mr.operation = "MULTIPLY"; SV(mr, 1, rough_mul)
        L.new(r.outputs["Color"], mr.inputs[0]); L.new(mr.outputs[0], b.inputs["Roughness"])
    n = img("nor_gl", True)
    if n:
        nm = N.new("ShaderNodeNormalMap"); SV(nm, "Strength", bump)
        L.new(n.outputs["Color"], nm.inputs["Color"]); L.new(nm.outputs["Normal"], b.inputs["Normal"])
    if emit:
        SV(b, "Emission Color", (*emit, 1))
        SV(b, "Emission Strength", es)
    MATS[name] = m
    return m

def gold_mat(name="gold", col=(1.0, 0.71, 0.29), rough=0.22):
    if name in MATS: return MATS[name]
    m = bpy.data.materials.new(name); m.use_nodes = True
    nt = m.node_tree; N = nt.nodes; L = nt.links
    b = N.get("Principled BSDF")
    SV(b, "Base Color", (*col, 1)); SV(b, "Metallic", 1.0)
    nz = N.new("ShaderNodeTexNoise"); SV(nz, "Scale", 60.0)
    mr = N.new("ShaderNodeMapRange"); SV(mr, "To Min", rough * 0.6); SV(mr, "To Max", rough * 1.5)
    L.new(nz.outputs["Fac"], mr.inputs["Value"]); L.new(mr.outputs["Result"], b.inputs["Roughness"])
    MATS[name] = m
    return m

# ---------------------------------------------------------------- mesh helpers
def mk(name, bm, m=None, loc=(0, 0, 0), rot=(0, 0, 0), smooth=False, parent=None, coll=None):
    me = bpy.data.meshes.new(name); bm.to_mesh(me); bm.free()
    if smooth:
        for p in me.polygons: p.use_smooth = True
    o = bpy.data.objects.new(name, me)
    if m: o.data.materials.append(m)
    o.location = loc; o.rotation_euler = rot
    if parent: o.parent = parent
    return link(o, coll)

def box(name, size, loc, m=None, bevel=0.0, rot=(0, 0, 0), parent=None, seg=2):
    bm = bmesh.new(); bmesh.ops.create_cube(bm, size=1.0)
    for v in bm.verts: v.co = Vector((v.co.x * size[0], v.co.y * size[1], v.co.z * size[2]))
    o = mk(name, bm, m, loc, rot, parent=parent)
    if bevel > 0:
        b = o.modifiers.new("bv", "BEVEL"); b.width = bevel; b.segments = seg; b.limit_method = "ANGLE"
        for p in o.data.polygons: p.use_smooth = True
    return o

def cyl(name, r, h, loc, m=None, seg=32, rot=(0, 0, 0), r2=None, parent=None, smooth=True):
    bm = bmesh.new()
    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=seg, radius1=r, radius2=(r if r2 is None else r2), depth=h)
    return mk(name, bm, m, loc, rot, smooth=smooth, parent=parent)

def sphere(name, rad, loc, m=None, scale=(1, 1, 1), parent=None, seg=(32, 16)):
    bm = bmesh.new(); bmesh.ops.create_uvsphere(bm, u_segments=seg[0], v_segments=seg[1], radius=rad)
    for v in bm.verts: v.co = Vector((v.co.x * scale[0], v.co.y * scale[1], v.co.z * scale[2]))
    return mk(name, bm, m, loc, smooth=True, parent=parent)

def plane(name, w, h, loc, m=None, rot=(0, 0, 0), parent=None):
    bm = bmesh.new()
    vs = [bm.verts.new((x * w / 2, y * h / 2, 0)) for (x, y) in [(-1, -1), (1, -1), (1, 1), (-1, 1)]]
    bm.faces.new(vs)
    return mk(name, bm, m, loc, rot, parent=parent)

def lathe(name, prof, m=None, loc=(0, 0, 0), seg=20, parent=None):
    """surface of revolution from profile [(r, z), ...] (bottom to top)"""
    bm = bmesh.new(); rings = []
    for (r, z) in prof:
        ring = [bm.verts.new((r * math.cos(2 * math.pi * i / seg), r * math.sin(2 * math.pi * i / seg), z)) for i in range(seg)]
        rings.append(ring)
    for a, b in zip(rings, rings[1:]):
        for i in range(seg):
            j = (i + 1) % seg
            bm.faces.new([a[i], a[j], b[j], b[i]])
    bm.faces.new(list(reversed(rings[0]))); bm.faces.new(rings[-1])
    return mk(name, bm, m, loc, smooth=True, parent=parent)

def prism(name, pts2d, depth, m=None, loc=(0, 0, 0), rot=(0, 0, 0), parent=None):
    """extrude a 2D polygon (x, z) along +y by depth"""
    bm = bmesh.new()
    f = [bm.verts.new((x, 0, z)) for (x, z) in pts2d]
    b_ = [bm.verts.new((x, depth, z)) for (x, z) in pts2d]
    bm.faces.new(f); bm.faces.new(list(reversed(b_)))
    n = len(pts2d)
    for i in range(n):
        j = (i + 1) % n
        bm.faces.new([f[i], f[j], b_[j], b_[i]])
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    return mk(name, bm, m, loc, rot, parent=parent)

def empty(name, loc=(0, 0, 0), rot=(0, 0, 0), parent=None):
    o = bpy.data.objects.new(name, None); o.location = loc; o.rotation_euler = rot
    o.empty_display_size = 0.1
    if parent: o.parent = parent
    return link(o)

def light(name, kind, loc, energy, col=(1, 0.8, 0.6), size=0.1, rot=(0, 0, 0), spot=None, shadow=True):
    ld = bpy.data.lights.new(name, kind); ld.energy = energy; ld.color = col
    if kind in ("POINT", "SPOT"): ld.shadow_soft_size = size
    if kind == "AREA": ld.size = size
    if kind == "SUN": ld.angle = size
    if spot: ld.spot_size = math.radians(spot); ld.spot_blend = 0.6
    setattr_safe(ld, "use_shadow", shadow)
    o = bpy.data.objects.new(name, ld); o.location = loc; o.rotation_euler = rot
    return link(o)

def aim(o, target):
    d = Vector(target) - o.location
    o.rotation_euler = d.to_track_quat("-Z", "Y").to_euler()

# ---------------------------------------------------------------- assets: instances (static) and copies (animated)
ASSET = {}
def _load(path):
    with bpy.data.libraries.load(path, link=False) as (df, dt):
        dt.objects = list(df.objects)
    return [o for o in dt.objects if o is not None]

def bbox_of(objs):
    mn = Vector((1e9, 1e9, 1e9)); mx = Vector((-1e9, -1e9, -1e9))
    for o in objs:
        if o.type != "MESH" or o.hide_render: continue
        for c in o.bound_box:
            w = o.matrix_world @ Vector(c)
            mn = Vector((min(mn.x, w.x), min(mn.y, w.y), min(mn.z, w.z)))
            mx = Vector((max(mx.x, w.x), max(mx.y, w.y), max(mx.z, w.z)))
    return mn, mx

HIDE_WORDS = ("logo", "badge", "emblem", "brand", "decal", "sticker", "text", "chevrolet", "chevy", "isuzu")
WIDGET = ("wgt", "cs_", "widget", "target.ik", "ik_target")
def is_widget(o): return o.name.lower().startswith(WIDGET)
def asset_path(key):
    if key.startswith("ph:"): return ph_model(key[3:])
    return bk_file(key)

FREEZE_SKIP = {"ARMATURE", "NODES", "PARTICLE_SYSTEM", "CLOTH", "SOFT_BODY", "FLUID", "DYNAMIC_PAINT", "OCEAN", "EXPLODE", "MESH_CACHE", "SURFACE_DEFORM", "MESH_DEFORM", "LAPLACIANDEFORM", "CORRECTIVE_SMOOTH", "BOOLEAN"}
def freeze(objs, tag="", live_subsurf=1, frozen_subsurf=2):
    """(from MT43 common_dl) static meshes: evaluate the modifier stack once and replace it by a plain mesh;
    deforming meshes keep their stack with SUBSURF capped (except Surface-Deform targets, whose vertex count must not change);
    mesh / shape-key drivers removed."""
    n = c = d = 0
    sd_targets = set()
    for o in objs:
        if o.type == "MESH":
            for m in o.modifiers:
                if m.type in ("SURFACE_DEFORM", "MESH_DEFORM") and getattr(m, "target", None) is not None: sd_targets.add(m.target.name)
    for o in objs:
        if o.type != "MESH": continue
        for idb in (o, o.data, getattr(o.data, "shape_keys", None)):
            ad = getattr(idb, "animation_data", None) if idb is not None else None
            if ad:
                for dr in list(ad.drivers):
                    try: ad.drivers.remove(dr); d += 1
                    except Exception: pass
        if not o.modifiers: continue
        kinds = {m.type for m in o.modifiers}
        if kinds & FREEZE_SKIP or o.name in sd_targets:
            if o.name not in sd_targets:
                for m in o.modifiers:
                    if m.type == "SUBSURF":
                        m.render_levels = min(m.render_levels, live_subsurf); m.levels = min(m.levels, live_subsurf); c += 1
            continue
        for m in o.modifiers:
            if m.type == "SUBSURF": m.levels = min(max(m.levels, m.render_levels), frozen_subsurf)
            if m.type == "MULTIRES":
                try: m.levels = min(m.render_levels, frozen_subsurf)
                except Exception: pass
    bpy.context.view_layer.update()
    dg = bpy.context.evaluated_depsgraph_get()
    for o in objs:
        if o.type != "MESH" or not o.modifiers: continue
        if {m.type for m in o.modifiers} & FREEZE_SKIP or o.name in sd_targets: continue
        try:
            oe = o.evaluated_get(dg)
            if oe is o: continue
            me = bpy.data.meshes.new_from_object(oe, preserve_all_data_layers=True, depsgraph=dg)
            o.modifiers.clear(); o.data = me; n += 1
        except Exception as e:
            NOTES.append("frz %s %s" % (o.name[:12], type(e).__name__))
    NOTES.append("frz%s %d/%d cap %d drv %d sdt %d" % (tag, n, len(objs), c, d, len(sd_targets)))
    return n

def load_asset(key, hide_extra=()):
    if key in ASSET: return ASSET[key]
    p = asset_path(key)
    if not p: ASSET[key] = None; return None
    try:
        objs = _load(p)
        coll = bpy.data.collections.new("A_" + key)
        for o in objs:
            if o.type in ("CAMERA", "LIGHT") or is_widget(o): continue
            nm = o.name.lower()
            if any(w in nm for w in HIDE_WORDS + tuple(hide_extra)) and o.type == "MESH":
                NOTES.append("hid " + o.name[:20]); continue
            coll.objects.link(o)
        try:
            bpy.context.scene.collection.children.link(coll)
            freeze(list(coll.objects), key)
        except Exception as e: NOTES.append("frz %s %s" % (key, type(e).__name__))
        try: bpy.context.scene.collection.children.unlink(coll)
        except Exception: pass
        bpy.context.view_layer.update()
        mn, mx = bbox_of(coll.objects)
        if mn.x > 1e8: raise RuntimeError("no mesh")
        coll.instance_offset = ((mn.x + mx.x) / 2, (mn.y + mx.y) / 2, mn.z)
        ASSET[key] = (coll, mx - mn)
